<div class="form-grid">
<div class="field"><label>Service requirement</label><select name="requirement_type"><?php foreach (['Life Limits','Overhaul Requirement','Inspection Requirement'] as $type): ?><option value="<?= esc($type) ?>" <?= ($record['requirement_type'] ?? '')===$type?'selected':'' ?>><?= esc($type) ?></option><?php endforeach; ?></select></div>
<div class="field"><label>Description</label><input name="description" maxlength="255" value="<?= esc($record['description'] ?? '') ?>" required></div>
<?php if ($c['track_calendar']): ?><div class="field"><label>Last complied date</label><input type="date" name="last_date" value="<?= esc($record['last_date'] ?? '') ?>"></div><?php endif; ?>
<?php if ($c['track_time']): ?><div class="field"><label>Last complied component hours</label><input type="number" name="last_hours" min="0" step="0.1" value="<?= esc($record['last_hours'] ?? '') ?>"></div><?php endif; ?>
<?php if ($c['track_cycles']): ?><div class="field"><label>Last complied component cycles</label><input type="number" name="last_cycles" min="0" step="1" value="<?= esc($record['last_cycles'] ?? '') ?>"></div><?php endif; ?>
<?php if ($c['track_time']): ?><div class="field"><label>Time interval (component hours)</label><input type="number" name="interval_hours" min="0.1" step="0.1" value="<?= esc($record['interval_hours'] ?? '') ?>"></div><?php endif; ?>
<?php if ($c['track_time']): ?><div class="field"><label>Time basis for this requirement</label><select name="time_basis"><?php foreach (['TSN'=>'Time Since New (TSN)','TSO'=>'Time Since Overhaul (TSO)','TSR'=>'Time Since Repair (TSR)'] as $basis=>$label): ?><option value="<?= $basis ?>" <?= ($record['time_basis'] ?? 'TSN')===$basis?'selected':'' ?>><?= esc($label) ?></option><?php endforeach; ?></select></div><?php endif; ?>
<?php if ($c['track_time']): ?><div class="field"><label>Hour limit basis</label><select name="time_limit_mode"><option value="ABSOLUTE" <?= ($record['time_limit_mode'] ?? 'ABSOLUTE')==='ABSOLUTE'?'selected':'' ?>>Absolute component total hours (e.g. due at 5,000)</option><option value="FROM_LAST_COMPLIED" <?= ($record['time_limit_mode'] ?? '')==='FROM_LAST_COMPLIED'?'selected':'' ?>>Hours after last compliance</option></select></div><?php endif; ?>
<?php if ($c['track_calendar']): ?><div class="field"><label>Calendar interval</label><input type="number" name="calendar_interval_value" min="1" step="1" value="<?= esc($record['calendar_interval_value'] ?? '') ?>"></div><?php endif; ?>
<?php if ($c['track_calendar']): ?><div class="field"><label>Calendar unit</label><select name="calendar_interval_unit"><?php foreach (['DAYS','MONTHS','YEARS'] as $unit): ?><option value="<?= $unit ?>" <?= ($record['calendar_interval_unit'] ?? 'MONTHS')===$unit?'selected':'' ?>><?= ucfirst(strtolower($unit)) ?></option><?php endforeach; ?></select></div><?php endif; ?>
<?php if ($c['track_cycles']): ?><div class="field"><label>Cycles interval</label><input type="number" name="interval_cycles" min="1" step="1" value="<?= esc($record['interval_cycles'] ?? '') ?>"></div><?php endif; ?>
<?php if ($c['track_cycles']): ?><div class="field"><label>Cycle limit basis</label><select name="cycle_limit_mode"><option value="ABSOLUTE" <?= ($record['cycle_limit_mode'] ?? 'ABSOLUTE')==='ABSOLUTE'?'selected':'' ?>>Absolute component total cycles</option><option value="FROM_LAST_COMPLIED" <?= ($record['cycle_limit_mode'] ?? '')==='FROM_LAST_COMPLIED'?'selected':'' ?>>Cycles after last compliance</option></select></div><?php endif; ?>
<?php if ($c['track_calendar']): ?><div class="field"><label>Due soon: calendar months</label><input type="number" name="warning_calendar_months" min="0" max="1200" step="1" value="<?= esc($record['warning_calendar_months'] ?? '1') ?>" required></div><?php endif; ?>
<?php if ($c['track_time']): ?><div class="field"><label>Due soon: component hours</label><input type="number" name="warning_hours" min="0" step="0.1" value="<?= esc($record['warning_hours'] ?? '25.0') ?>" required></div><?php endif; ?>
<?php if ($c['track_cycles']): ?><div class="field"><label>Due soon: component cycles</label><input type="number" name="warning_cycles" min="0" max="1000000" step="1" value="<?= esc($record['warning_cycles'] ?? '10') ?>" required></div><?php endif; ?>
<div class="field full"><label>Notes</label><textarea name="notes" maxlength="10000"><?= esc($record['notes'] ?? '') ?></textarea></div>
</div>
